def minTime(n, edges, k):
    def comp(t):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        c = n
        for u, v, tm in edges:
            if tm > t:
                ru, rv = find(u), find(v)
                if ru != rv:
                    parent[ru] = rv
                    c -= 1
        return c

    times = sorted(set([0] + [e[2] for e in edges]))
    l, r = 0, len(times) - 1
    res = None
    while l <= r:
        mid = (l + r) // 2
        if comp(times[mid]) >= k:
            res = times[mid]
            r = mid - 1
        else:
            l = mid + 1
    return res if res is not None else -1
